param([switch]$RegisterService,[switch]$ProvisionReadOnlyDatabase)
$ErrorActionPreference='Stop'
if(-not(Get-PSProvider Certificate -ErrorAction SilentlyContinue)){Remove-TypeData -TypeName 'System.Security.AccessControl.ObjectSecurity' -ErrorAction SilentlyContinue;Import-Module Microsoft.PowerShell.Security -ErrorAction Stop}
$target=Join-Path $env:ProgramFiles 'PaperfundSigner';$report=Join-Path $env:ProgramData 'PaperfundSignerAcceptance\automation-install.public.json'
try{
 $identity=[Security.Principal.WindowsIdentity]::GetCurrent();$principal=New-Object Security.Principal.WindowsPrincipal($identity);if(-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Administrator deployment approval required'}
 $admin=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544');$system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18');$signer=Get-LocalUser PaperfundSigner;$operator=Get-LocalUser stanp
 if((Get-Acl $target).GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $admin.Value -or ((Get-Item $target).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Untrusted existing signer installation'}
 $manifest=Get-Content (Join-Path $PSScriptRoot 'automation-install-manifest.json') -Raw|ConvertFrom-Json
 foreach($entry in $manifest.files){if($entry.name -notmatch '^(automation-[a-z-]+\.(ps1|bundle\.cjs)|authorize-automation\.ps1|open-automation-custody\.ps1|enroll-automation-custody\.ps1|grant-automation-batch\.ps1)$'){throw 'Invalid deployment path'};$source=Join-Path $PSScriptRoot $entry.name;$dest=Join-Path $target $entry.name;if((Get-FileHash $source).Hash -ne $entry.sha256){throw 'Reviewed source hash mismatch'};if((Test-Path $dest) -and (Get-FileHash $dest).Hash -ne $entry.sha256){throw 'Existing different automation component preserved'}}
 foreach($entry in $manifest.files){$source=Join-Path $PSScriptRoot $entry.name;$dest=Join-Path $target $entry.name;if(-not(Test-Path $dest)){[IO.File]::Copy($source,$dest,$false);$acl=Get-Acl $dest;$acl.SetOwner($admin);Set-Acl $dest $acl}}
 $manifestDest=Join-Path $target 'automation-install-manifest.json';if(Test-Path $manifestDest){if((Get-FileHash $manifestDest).Hash -ne (Get-FileHash (Join-Path $PSScriptRoot 'automation-install-manifest.json')).Hash){throw 'Existing manifest differs; reviewed update required'}}else{[IO.File]::Copy((Join-Path $PSScriptRoot 'automation-install-manifest.json'),$manifestDest,$false);$acl=Get-Acl $manifestDest;$acl.SetOwner($admin);Set-Acl $manifestDest $acl}
 function Set-DirectoryAcl([string]$dir,[string]$signerRights,[string]$operatorRights){if(Test-Path $dir){if((Get-Item $dir).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'IPC reparse point'}};[IO.Directory]::CreateDirectory($dir)|Out-Null;$acl=(New-Object IO.DirectoryInfo($dir)).GetAccessControl([Security.AccessControl.AccessControlSections]::Access);$acl.SetAccessRuleProtection($true,$false);foreach($r in @($acl.Access)){$acl.RemoveAccessRuleSpecific($r)};$acl.SetOwner($admin);foreach($sid in @($admin,$system)){$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow')))};$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($signer.SID,$signerRights,'ContainerInherit,ObjectInherit','None','Allow')));$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($operator.SID,$operatorRights,'ContainerInherit,ObjectInherit','None','Allow')));(New-Object IO.DirectoryInfo($dir)).SetAccessControl($acl)}
 $ipc=Join-Path $env:ProgramData 'PaperfundAutomation';Set-DirectoryAcl $ipc 'ReadAndExecute' 'ReadAndExecute';Set-DirectoryAcl (Join-Path $ipc 'inbox') 'Modify' 'Modify';Set-DirectoryAcl (Join-Path $ipc 'public') 'Modify' 'ReadAndExecute';Set-DirectoryAcl (Join-Path $ipc 'rejected') 'Modify' 'ReadAndExecute'
 $configPath=Join-Path $target 'automation-config.json';if(-not(Test-Path $configPath)){$rpc=Get-Content (Join-Path $target 'claim-rpc.json') -Raw|ConvertFrom-Json;[IO.File]::WriteAllText($configPath,(@{rpcEndpoint=$rpc.endpoint;readonlyDatabaseUrl=$null;signerSid=$signer.SID.Value}|ConvertTo-Json -Compress),(New-Object Text.UTF8Encoding($false)))}
 function Protect-Config { $acl=Get-Acl $configPath;$acl.SetAccessRuleProtection($true,$false);foreach($r in @($acl.Access)){$acl.RemoveAccessRuleSpecific($r)};$acl.SetOwner($admin);foreach($sid in @($admin,$system)){$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($sid,'FullControl','Allow')))};$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($signer.SID,'ReadAndExecute','Allow')));Set-Acl $configPath $acl }
 Protect-Config
 $revocationPath=Join-Path $target 'policy-revocations.json';if(-not(Test-Path $revocationPath)){[IO.File]::WriteAllText($revocationPath,'[]',(New-Object Text.UTF8Encoding($false)));$acl=Get-Acl $revocationPath;$acl.SetOwner($admin);Set-Acl $revocationPath $acl}
 if($ProvisionReadOnlyDatabase){$repository=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent;& (Join-Path $env:ProgramFiles 'nodejs\node.exe') (Join-Path $target 'automation-configure.bundle.cjs') $repository;if($LASTEXITCODE -ne 0){throw 'Dedicated read-only DB role setup blocked'};Protect-Config}
 $registered=$false
 if($RegisterService){
  & (Join-Path $target 'grant-automation-batch.ps1')
  if($LASTEXITCODE -eq 2){throw 'Explicit batch denial requires review'}
  if(Get-ScheduledTask -TaskName 'PaperfundIsolatedAutomation' -ErrorAction SilentlyContinue){throw 'Existing scheduled task retained; inspect before changing'}
  Write-Host 'Enter only the existing PaperfundSigner WINDOWS account password locally. No wallet key is requested.'
  $secure=Read-Host 'PaperfundSigner Windows password (hidden)' -AsSecureString;$plain=$null;$pointer=[IntPtr]::Zero
  try{$pointer=[Runtime.InteropServices.Marshal]::SecureStringToGlobalAllocUnicode($secure);$plain=[Runtime.InteropServices.Marshal]::PtrToStringUni($pointer);$action=New-ScheduledTaskAction -Execute (Join-Path $PSHOME 'powershell.exe') -Argument ('-NoProfile -ExecutionPolicy RemoteSigned -File "'+(Join-Path $target 'automation-host.ps1')+'"') -WorkingDirectory $target;$trigger=New-ScheduledTaskTrigger -AtStartup;$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries;Register-ScheduledTask -TaskName 'PaperfundIsolatedAutomation' -Description 'Paperfund isolated policy-gated automation' -Action $action -Trigger $trigger -Settings $settings -User ($env:COMPUTERNAME+'\PaperfundSigner') -Password $plain -RunLevel Limited|Out-Null;$registered=$true;Start-ScheduledTask -TaskName 'PaperfundIsolatedAutomation'}finally{$plain=$null;if($pointer -ne [IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($pointer)};$secure.Dispose()}
 }
 @{installed=$true;registered=$registered;standingAuthority='NONE';channels='ALL_OFF';legacyClaimRuntimeUnchanged=$true;at=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content $report
 Write-Host 'Automation installed with NO standing authority. Global STOP and all financial gates preserved.'
}catch{@{installed=$false;error=$_.Exception.Message;at=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content $report;Write-Host ('AUTOMATION SETUP BLOCKED: '+$_.Exception.Message) -ForegroundColor Red}
Read-Host 'Press Enter to close setup'|Out-Null
